352	    /**
353	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
354	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
355	     * (absent) or already valid.
356	     *
357	     * @param email the email address as submitted, or {@code null} when absent
358	     * @return the lower-cased email, or {@code null} when absent
359	     */
360	    private String normalizeEmail(String email) {
361	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
362	    }
